parameters.jsCode:
// Validierung, Normalisierung und Spam-Abwehr — serverseitig.
// Der clientseitige Honeypot/Zeit-Check ist nur Komfort; verlassen darf man sich
// ausschliesslich auf das, was hier passiert.

const body = $input.first().json.body ?? $input.first().json;
const headers = $input.first().json.headers ?? {};

// Steuerzeichen raus: name und betrieb landen in der Betreffzeile der
// Benachrichtigung. Ein Zeilenumbruch dort ist keine Luecke — der Mailversand
// kodiert den Betreff und entschaerft ihn dabei — aber gebastelte Betreffzeilen
// im eigenen Posteingang will man trotzdem nicht.
const clean = (v, max = 2000) =>
  typeof v === 'string' ? v.replace(/[\r\n\t]+/g, ' ').trim().slice(0, max) : '';

// Die Nachricht behaelt ihre Absaetze, nur \r fliegt raus.
const cleanText = (v, max = 5000) =>
  typeof v === 'string' ? v.replace(/\r/g, '').trim().slice(0, max) : '';

const name       = clean(body.name, 120);
const betrieb    = clean(body.betrieb, 160);
const telefon    = clean(body.telefon, 60);
const email      = clean(body.email, 200).toLowerCase();
const nachricht  = cleanText(body.nachricht, 5000);
const quelle     = clean(body.quelle, 60) || 'website-kontaktformular';
const honeypot   = clean(body.website, 200);
const einwilligung = body.einwilligung === 'on' || body.einwilligung === true;

// --- Anliegen (die Chips im Formular) ---------------------------------------
// Optional: keine Validierungsregel, eine leere Auswahl ist voellig in Ordnung.
// Die Whitelist ist Pflicht, nicht Kosmetik: der Webhook ist oeffentlich, jeder
// kann per curl beliebigen Text als "anliegen" schicken. Ohne den Filter stuende
// dieser Text woertlich in meiner Benachrichtigungs-Mail — an einer Stelle, der
// ich vertraue. Durchgelassen wird deshalb nur, was hier aufgelistet ist.
const ANLIEGEN = {
  anrufe:     'Anrufe gehen verloren',
  angebote:   'Angebote dauern zu lang',
  doku:       'Baustellen-Doku',
  rechnungen: 'Rechnungen & Mahnungen',
  unklar:     'Noch unklar',
};

const anliegenRoh = Array.isArray(body.anliegen) ? body.anliegen : [];
const anliegen = anliegenRoh
  .filter((k) => typeof k === 'string' && k in ANLIEGEN)
  .slice(0, 5);

// Fuer die Mail: lesbare Liste, sonst ein Gedankenstrich.
const anliegenText = anliegen.length
  ? anliegen.map((k) => ANLIEGEN[k]).join(' · ')
  : '—';

// Fuer Postgres (Spalte anliegen TEXT[]): Array-Literal wie {anrufe,rechnungen}.
// Kein Escaping noetig — die Schluessel bestehen nur aus Kleinbuchstaben und
// haben die Whitelist oben passiert.
const anliegenSql = '{' + anliegen.join(',') + '}';

const fehler = [];

// 1) Honeypot — Bots fuellen das unsichtbare Feld aus.
if (honeypot) fehler.push('honeypot');

// 2) Pflichtfelder. Obergrenzen stehen oben in clean() — zu lange Felder werden
//    gekappt, nicht abgewiesen; ein Kunde soll nicht wegen Textlaenge scheitern.
//    Uebergrosse Anfragen faengt die 32-KB-Grenze in Caddy ab, bevor n8n startet.
if (name.length < 2)      fehler.push('name');
if (telefon.length < 5)   fehler.push('telefon');
if (nachricht.length < 5) fehler.push('nachricht');
if (!einwilligung)        fehler.push('einwilligung');

// 3) E-Mail-Format
if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email)) fehler.push('email');

// 4) Rate-Limit: max. 3 ANGENOMMENE Anfragen pro IP in 10 Minuten.
//    Static Data ueberlebt Workflow-Ausfuehrungen; kein externer Speicher noetig.
const FENSTER_MS = 10 * 60 * 1000;
const MAX = 3;
const store = $getWorkflowStaticData('global');
store.treffer = store.treffer || {};
// Tages-Salt fuer die IP-Pseudonymisierung. Nie ausgeben, nie loggen; taeglich neu,
// damit sich Hashes nicht ueber Tage zu einem Bewegungsprofil verketten lassen.
const crypto = require('crypto');
const heuteUTC = new Date().toISOString().slice(0, 10);
if (store.saltDatum !== heuteUTC) {
  store.salt = crypto.randomBytes(16).toString('hex');
  store.saltDatum = heuteUTC;
}
// Hygiene: nur 64-stellige Hex-Hashes als Schluessel dulden. Aeltere Klartext-IP-
// Schluessel aus der Zeit vor dieser Aenderung fallen damit sofort vollstaendig raus.
for (const migK of Object.keys(store.treffer)) {
  if (!/^[0-9a-f]{64}$/.test(migK)) delete store.treffer[migK];
}
const jetzt = Date.now();

// alte Eintraege aufraeumen, damit der Speicher nicht unbegrenzt waechst
for (const [k, zeiten] of Object.entries(store.treffer)) {
  const frisch = zeiten.filter((t) => jetzt - t < FENSTER_MS);
  if (frisch.length) store.treffer[k] = frisch;
  else delete store.treffer[k];
}

// Client-IP aus X-Forwarded-For. Der Header ist eine KETTE, und der eigene
// Proxy haengt hinten an — was der Absender selbst mitschickt, steht davor.
// Deshalb das letzte Glied lesen, nicht das erste: sonst setzt sich jeder mit
// einem erfundenen X-Forwarded-For beliebig oft seinen eigenen Zaehler zurueck.
// Caddy ueberschreibt den Header zusaetzlich (header_up X-Forwarded-For).
const xff = String(headers['x-forwarded-for'] || '').split(',');
const ip = xff[xff.length - 1].trim() || 'unbekannt';

// IP nur pseudonymisiert weiterverwenden: sha256(ip + Tages-Salt) als Schluessel.
// Der Klartext bleibt allein in dieser lokalen Variablen (Arbeitsspeicher), wird
// weder in store.* geschrieben noch ausgegeben.
const ipHash = crypto.createHash('sha256').update(ip + store.salt).digest('hex');

if ((store.treffer[ipHash] || []).length >= MAX) fehler.push('rate-limit');

// 5) Plumpe Spam-Heuristik: Links in der Nachricht sind bei Handwerksanfragen
//    praktisch nie echt.
const linkAnzahl = (nachricht.match(/https?:\/\//gi) || []).length;
if (linkAnzahl >= 2) fehler.push('spam-links');

const gueltig = fehler.length === 0;

// --- Zaehler erst JETZT erhoehen, und nur fuer angenommene Anfragen ----------
// Vorher lief das Hochzaehlen bedingungslos. Folge: jeder Versuch schob einen
// neuen Zeitstempel nach, das Fenster wanderte mit, die Sperre endete nie —
// nachgemessen am 17.08.2026, 01:14 bis 01:28: fuenfzehn Anfragen im
// Minutentakt, alle abgewiesen, obwohl das Fenster zehn Minuten misst.
// Zwei Wirkungen der Umstellung:
//   - Wer gesperrt ist, verlaengert seine Sperre nicht durch weitere Versuche.
//   - Wer sich beim Ausfuellen dreimal vertippt, wird nicht ausgesperrt.
// Reine Last durch ungueltige Anfragen faengt die Drossel in Caddy ab.
if (gueltig) {
  store.treffer[ipHash] = [...(store.treffer[ipHash] || []), jetzt];
}

// --- Bremse fuer die Auto-Antwort -------------------------------------------
// Die Auto-Antwort geht an die Adresse, die im Formular steht. Ohne Bremse
// laesst sich der Endpunkt benutzen, um ueber kontakt@roehrner.eu wiederholt
// Fremde anzuschreiben — und das trifft die Zustellbarkeit der eigenen Domain.
// Hoechstens eine Auto-Antwort pro Empfaenger und Stunde. Die Benachrichtigung
// an mich selbst laeuft unabhaengig davon weiter.
const FENSTER_AUTO_MS = 60 * 60 * 1000;
store.autoAntwortAn = store.autoAntwortAn || {};
for (const [k, t] of Object.entries(store.autoAntwortAn)) {
  if (jetzt - t >= FENSTER_AUTO_MS) delete store.autoAntwortAn[k];
}

// Zweite Achse: eine GESAMTZAHL pro Stunde. Die Sperre pro Adresse verhindert
// nur, dass DIESELBE Adresse mehrfach angeschrieben wird. Sie begrenzt nicht,
// wie viele VERSCHIEDENE Fremde erreicht werden — und genau daraus entsteht der
// Reputationsschaden: viele einzelne Mails an je einen Unbeteiligten, die dort
// als unverlangt ankommen. 12/h liegt weit ueber jedem realen Anfrageaufkommen
// und weit unter dem, was einer frischen Domain die Zustellbarkeit kostet.
const AUTO_MAX_PRO_STUNDE = 12;
store.autoAntwortVersand = (store.autoAntwortVersand || []).filter(
  (t) => jetzt - t < FENSTER_AUTO_MS
);
const kontingentFrei = store.autoAntwortVersand.length < AUTO_MAX_PRO_STUNDE;

const autoAntwort = gueltig && !store.autoAntwortAn[email] && kontingentFrei;
if (autoAntwort) {
  store.autoAntwortAn[email] = jetzt;
  store.autoAntwortVersand.push(jetzt);
}

// --- M4: Abwehr nicht benennen ----------------------------------------------
// Eine Antwort wie {"fehler":["honeypot"]} ist eine Bauanleitung: der Bot-Autor
// sieht genau, welche Regel gegriffen hat, und stellt sie ab. Fuer diese beiden
// Faelle sieht die Antwort nach aussen deshalb aus wie ein Erfolg — versendet
// wird trotzdem nichts. Feldfehler und rate-limit bleiben sprechend, die
// braucht das Formular fuer eine brauchbare Rueckmeldung an echte Kunden.
const STILL = new Set(['honeypot', 'spam-links']);
const still = !gueltig && fehler.length > 0 && fehler.every((f) => STILL.has(f));

const eingegangenAm = new Date().toISOString();

return [{
  json: {
    gueltig,
    autoAntwort,
    still,
    fehler,
    eingegangenAm,
    eingegangenAmLesbar: new Date(eingegangenAm).toLocaleString('de-DE', {
      timeZone: 'Europe/Berlin',
      dateStyle: 'full',
      timeStyle: 'short',
    }),
    name,
    betrieb: betrieb || '—',
    betriebSql: betrieb || null,
    telefon,
    email,
    nachricht,
    quelle,
    anliegen,
    anliegenText,
    anliegenSql,
  },
}];

